use clap::{Command,CommandFactory};use schemars::JsonSchema;use serde::{Deserialize,Serialize};
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize,JsonSchema)]pub struct CliCommandSchema{pub name:String,pub about:Option<String>,pub version:Option<String>,pub arguments:Vec<CliArgSchema>,pub subcommands:Vec<CliCommandSchema>}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize,JsonSchema)]pub struct CliArgSchema{pub id:String,pub short:Option<char>,pub long:Option<String>,pub positional_index:Option<usize>,pub action:String,pub required:bool,pub num_args:Option<String>,pub value_names:Vec<String>,pub possible_values:Vec<String>,pub default_values:Vec<String>,pub value_delimiter:Option<char>,pub require_equals:bool,pub trailing_var_arg:bool,pub last:bool,pub help:Option<String>}
pub fn cli_schema<T:CommandFactory>()->CliCommandSchema{cli_schema_from_command(T::command())}pub fn cli_schema_value<T:CommandFactory>()->serde_json::Value{serde_json::to_value(cli_schema::<T>()).expect("schema serializes")}
pub fn cli_schema_from_command(mut command:Command)->CliCommandSchema{command.build();command_schema(&command)}
fn command_schema(command:&Command)->CliCommandSchema{let arguments=command.get_arguments().map(|arg|CliArgSchema{id:arg.get_id().as_str().to_owned(),short:arg.get_short(),long:arg.get_long().map(ToOwned::to_owned),positional_index:arg.get_index(),action:format!("{:?}",arg.get_action()),required:arg.is_required_set(),num_args:arg.get_num_args().map(|r|format!("{r:?}")),value_names:arg.get_value_names().map_or_else(Vec::new,|n|n.iter().map(ToString::to_string).collect()),possible_values:arg.get_possible_values().into_iter().map(|v|v.get_name().to_owned()).collect(),default_values:arg.get_default_values().iter().map(|v|v.to_string_lossy().into_owned()).collect(),value_delimiter:arg.get_value_delimiter(),require_equals:arg.is_require_equals_set(),trailing_var_arg:arg.is_trailing_var_arg_set(),last:arg.is_last_set(),help:arg.get_help().map(ToString::to_string)}).collect();CliCommandSchema{name:command.get_name().to_owned(),about:command.get_about().map(ToString::to_string),version:command.get_version().map(ToOwned::to_owned),arguments,subcommands:command.get_subcommands().map(command_schema).collect()}}
